    #[cfg(target_arch = "x86_64")]
    #[test]
    fn page_map_failure_at_first_allocation_start_is_retained_without_restart() {
        crate::test_process::run_in_fresh_process(
            "runtime_lifecycle::tests::page_map_failure_at_first_allocation_start_is_retained_without_restart",
            || {
                assert!(publish_native_process_startup_facts(host_startup_facts()));
                // The first raw mapping in the once body reserves the PageMap.
                let fault = fault::install(fault::Plan::at(fault::Point::Map, 1, Errno::NOMEM));
                assert!(matches!(native_allocate_aligned(48, 16, false),
                    NativePageAllocationResult::Unavailable));
                assert_eq!(fault.observed(), 1);
                assert_eq!(RUNTIME_PROCESS.state.load(Ordering::Acquire), PROCESS_RETAINED,
                    "a post-claim PageMap failure is terminal for this process");
                // Observe every later primitive without failing any.
                fault.set(fault::Plan::any_nth(usize::MAX, Errno::NOMEM));

                // Neither a later allocation nor the runtime startup call can
                // reopen the retained once body.
                assert!(matches!(native_allocate_aligned(48, 16, false),
                    NativePageAllocationResult::Unavailable));
                assert!(!initialize_process());
                assert!(!process_is_active());
                assert_eq!(fault.observed(), 0, "no retried source startup reached a primitive");
            },
        );
    }

    /// First recursive allocation result observed from inside a startup
    /// primitive: 0 none, 1 allocated, 2 unavailable, 3 other.
    #[cfg(target_arch = "x86_64")]
    static STARTUP_RECURSION_RESULT: core::sync::atomic::AtomicU8 = core::sync::atomic::AtomicU8::new(0);
    #[cfg(target_arch = "x86_64")]
    static STARTUP_RECURSION_REENTERED_STARTUP: core::sync::atomic::AtomicU8 =
        core::sync::atomic::AtomicU8::new(0);

    /// Performs one recursive native allocation from a startup primitive,
    /// frees it if it was granted, and records the outcome once.
    #[cfg(target_arch = "x86_64")]
    fn record_startup_recursive_allocation() {
        if STARTUP_RECURSION_RESULT.load(Ordering::Acquire) != 0 { return; }
        let outcome = match native_allocate_aligned(32, 16, false) {
            NativePageAllocationResult::Allocated(block) => {
                // SAFETY: the recursive client is exclusively owned here.
                unsafe { block.as_ptr().write_bytes(0x2d, 32) };
                // SAFETY: `block` is this thread's exact live native client.
                assert_eq!(unsafe { native_free(block) }, NativePageFreeResult::Freed);
                1
            }
            NativePageAllocationResult::Unavailable => 2,
            _ => 3,
        };
        STARTUP_RECURSION_RESULT.store(outcome, Ordering::Release);
    }

    /// A FILE primitive that allocates and re-enters runtime startup while
    /// the loader tail flushes delayed output through it.
    #[cfg(target_arch = "x86_64")]
    unsafe extern "C" fn allocating_startup_stderr(message: *const core::ffi::c_char) {
        record_startup_recursive_allocation();
        if STARTUP_RECURSION_REENTERED_STARTUP.load(Ordering::Acquire) == 0 {
            STARTUP_RECURSION_REENTERED_STARTUP.store(
                if initialize_process() { 1 } else { 2 }, Ordering::Release);
        }
        // SAFETY: forwarded source message.
        unsafe { capture_startup_stderr(message) };
    }

    #[cfg(target_arch = "x86_64")]
    fn allocating_output_startup_facts() -> NativeProcessStartupFacts {
        // SAFETY: immutable static reader vector; process-lifetime primitive.
        unsafe {
            NativeProcessStartupFacts::new(
                4096,
                delayed_warning_environment,
                RuntimeStderrOutput::new(allocating_startup_stderr),
            )
        }
        .expect("the native x86 fixture uses a supported base page size")
    }

    #[cfg(target_arch = "x86_64")]
    #[test]
    fn output_recursion_in_the_runtime_startup_tail_allocates_through_the_initial_owner() {
        crate::test_process::run_in_fresh_process(
            "runtime_lifecycle::tests::output_recursion_in_the_runtime_startup_tail_allocates_through_the_initial_owner",
            || {
                assert!(publish_native_process_startup_facts(allocating_output_startup_facts()));
                assert!(initialize_process());
                assert_eq!(STARTUP_RECURSION_RESULT.load(Ordering::Acquire), 1,
                    "post-init output may allocate through the published initial owner");
                assert_eq!(STARTUP_RECURSION_REENTERED_STARTUP.load(Ordering::Acquire), 1,
                    "a recursive startup call returns without waiting on its own once");
                // The one delayed flush is followed by `_mi_options_post_init`'s
                // verbose `mi_options_print`, one delivery per line.
                assert_eq!(STARTUP_STDERR_CAPTURE.delayed_flushes.load(Ordering::Acquire), 1,
                    "the recursive call did not flush a second time");
                assert!(process_is_active());
                assert!(native_round_trip(48));
            },
        );
    }

    #[cfg(target_arch = "x86_64")]
    #[test]
    fn output_recursion_in_the_deferred_loader_tail_allocates_through_the_initial_owner() {
        crate::test_process::run_in_fresh_process(
            "runtime_lifecycle::tests::output_recursion_in_the_deferred_loader_tail_allocates_through_the_initial_owner",
            || {
                assert!(publish_native_process_startup_facts(allocating_output_startup_facts()));
                assert!(native_round_trip(48));
                assert_eq!(STARTUP_RECURSION_RESULT.load(Ordering::Acquire), 0,
                    "no output reached the FILE primitive before the loader tail");
                assert!(initialize_process());
                assert_eq!(STARTUP_RECURSION_RESULT.load(Ordering::Acquire), 1);
                assert_eq!(STARTUP_RECURSION_REENTERED_STARTUP.load(Ordering::Acquire), 1);
                assert_eq!(STARTUP_STDERR_CAPTURE.delayed_flushes.load(Ordering::Acquire), 1);
                assert!(native_round_trip(64));
            },
        );
    }

    #[cfg(target_arch = "x86_64")]
    #[test]
    fn runtime_process_once_waits_for_terminal_startup_and_refuses_owner_reentry() {
        use std::time::{Duration, Instant};

        for terminal in [PROCESS_ACTIVE, PROCESS_RETAINED] {
            let runtime: &'static RuntimeProcessStorage = std::boxed::Box::leak(
                std::boxed::Box::new(RuntimeProcessStorage::new()));
            let (claimed_tx, claimed_rx) = mpsc::channel();
            let (release_tx, release_rx) = mpsc::channel();
            let initializer = thread::spawn(move || {
                let completion = runtime.begin_initialization_once()
                    .expect("the first caller claims source process startup");
                runtime.state.store(PROCESS_INITIALIZING, Ordering::Release);
                assert!(runtime.begin_initialization_once().is_none(),
                    "the initializing thread cannot wait on its own once lock");
                let identity = current_thread_identity().expect("the test caller has compiler TLS");
                runtime.initial_thread_identity.store(identity.get(), Ordering::Relaxed);
                runtime.state.store(PROCESS_ALLOCATABLE, Ordering::Release);
                assert!(runtime.is_on_initial_allocation_thread(),
                    "the source-attached owner can use its startup allocation lease");
                assert!(runtime.begin_initialization_once().is_none(),
                    "source diagnostic reentry still cannot wait on its own once lock");
                claimed_tx.send(()).unwrap();
                release_rx.recv().unwrap();
                runtime.state.store(terminal, Ordering::Release);
                completion.complete().expect("the source once lock releases");
            });
            claimed_rx.recv_timeout(Duration::from_secs(2)).unwrap();

            let (started_tx, started_rx) = mpsc::channel();
            let (observed_tx, observed_rx) = mpsc::channel();
            let contender = thread::spawn(move || {
                started_tx.send(()).unwrap();
                let received_claim = runtime.begin_initialization_once().is_some();
                observed_tx.send((received_claim, runtime.state.load(Ordering::Acquire))).unwrap();
            });
            started_rx.recv_timeout(Duration::from_secs(2)).unwrap();
            let deadline = Instant::now() + Duration::from_secs(2);
            while !runtime.process_once.test_is_contended() {
                assert!(Instant::now() < deadline,
                    "the contender reaches the runtime process once lock");
                thread::yield_now();
            }
            assert!(observed_rx.recv_timeout(Duration::from_millis(50)).is_err(),
                "a distinct caller must wait for the terminal startup publication");
            release_tx.send(()).unwrap();
            assert_eq!(observed_rx.recv_timeout(Duration::from_secs(2)).unwrap(),
                (false, terminal));
            initializer.join().unwrap();
            contender.join().unwrap();
        }
    }

    struct CurrentThreadDescriptorRegistry(NonNull<admission::NativeAllocatorThreadDescriptor>);

    // SAFETY: the fresh-process fixture retains this current TLS descriptor
    // and its owning thread slot for the synchronous terminal scan. It starts
    // no other thread and invokes no source owner transfer.
    unsafe impl admission::NativeAllocatorPinnedThreadRegistry for CurrentThreadDescriptorRegistry {
        fn visit_descriptors(
            &self,
            visitor: &mut dyn FnMut(NonNull<admission::NativeAllocatorThreadDescriptor>),
        ) {
            visitor(self.0);
        }
    }

    unsafe extern "C" fn observe_native_deferred_free_callback(
        force: bool,
        _heartbeat: u64,
        _context: *mut core::ffi::c_void,
    ) {
        // SAFETY: this is compiler TLS and the callback executes
        // synchronously on the selecting allocator thread. The focused
        // fixture marks only its worker thread, so unrelated parallel tests
        // cannot perturb this assertion even though the source registration
        // is process-global.
        if !unsafe { NATIVE_DEFERRED_FREE_TEST_THREAD_ACTIVE } {
            return;
        }
        NATIVE_DEFERRED_FREE_CALLBACK_FORCE.store(usize::from(force), Ordering::Release);
        NATIVE_DEFERRED_FREE_CALLBACK_COUNT.fetch_add(1, Ordering::AcqRel);
    }

    struct NativeDeferredFreeBoundaryObservation {
        callback_count: AtomicUsize,
        outer_operation_suspended: AtomicUsize,
        callback_marker_live: AtomicUsize,
        nested_native_round_trips: AtomicUsize,
    }

    unsafe extern "C" fn observe_native_deferred_free_boundary_callback(
        _force: bool,
        _heartbeat: u64,
        context: *mut core::ffi::c_void,
    ) {
        // SAFETY: the focused driver test owns this stack observation until
        // both selected source callbacks returned and unregisters only after
        // its initial thread and joined worker have completed phase C.
        let observation = unsafe { &*context.cast::<NativeDeferredFreeBoundaryObservation>() };
        let (outer_entered, callback_marker) =
            admission::current_native_allocator_callback_boundary_state();
        observation
            .outer_operation_suspended
            .fetch_add(usize::from(!outer_entered), Ordering::AcqRel);
        observation
            .callback_marker_live
            .fetch_add(usize::from(callback_marker), Ordering::AcqRel);

        // This is a normal native boundary entry, not a direct owner-cell or
        // page-engine projection. It must acquire a fresh nested operation
        // while the outer B operation is suspended, then free the exact live
        // client through the same guarded native interface.
        let completed = match native_allocate_aligned(16, NATIVE_C_MALLOC_ALIGNMENT, false) {
            NativePageAllocationResult::Allocated(block) => {
                matches!(unsafe { native_free(block) }, NativePageFreeResult::Freed)
            }
            NativePageAllocationResult::Unavailable
            | NativePageAllocationResult::AllocationFailed
            | NativePageAllocationResult::Retained => false,
        };
        observation
            .nested_native_round_trips
            .fetch_add(usize::from(completed), Ordering::AcqRel);
        observation.callback_count.fetch_add(1, Ordering::AcqRel);
    }

    fn native_deferred_free_boundary_outer_round_trip() -> bool {
        match native_allocate_aligned(2048, NATIVE_C_MALLOC_ALIGNMENT, false) {
            NativePageAllocationResult::Allocated(block) => {
                matches!(unsafe { native_free(block) }, NativePageFreeResult::Freed)
            }
            NativePageAllocationResult::Unavailable
            | NativePageAllocationResult::AllocationFailed
            | NativePageAllocationResult::Retained => false,
        }
    }

    fn drive_native_deferred_free_boundary_callback_once() {
        // The native source counter can enter with a nonzero startup value,
        // but any consecutive 1,000 generic requests select exactly one Mini
        // administration. Each request frees its exact current client before
        // the next, so this does not test arena exhaustion or page retirement.
        for _ in 0..1_000 {
            assert!(
                native_deferred_free_boundary_outer_round_trip(),
                "the outer native driver retains its exact source client through phase C"
            );
        }
    }

